#include <cstddef>
#include <iostream>
#include <memory>

struct Buffer {
    std::size_t size;
    std::unique_ptr<int[]> data;

    explicit Buffer(std::size_t n)
        : size(n), data(std::make_unique<int[]>(n)) {
    }
};

int main() {
    Buffer a(4);
    a.data[0] = 7;

    std::cout << "size=" << a.size << '\n';
    std::cout << "first=" << a.data[0] << '\n';
}
